def cast_qs(show,cast,extra):
    out=[]; acts=[a for _,a in cast]; chars=[c for c,_ in cast]
    for c,a in cast:
        out.append((f"من الممثل الذي أدى شخصية «{c}» في مسلسل {show}؟",o(a,acts)))
        out.append((f"ما الشخصية التي أداها {a} في مسلسل {show}؟",o(c,chars)))
    out+=[(q,(opts if isinstance(opts,list) and len(opts)==4 else o(a,opts))) if False else (q,o(a,d)) for q,a,d in extra]
    return out
